int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev) {
    if (!g || drive < 0 || drive >= N_DRIVE) {
        return -EINVAL;
    }

    if (type != -1) {
        if (!capable(CAP_SYS_ADMIN)) {
            return -EPERM;
        }

        if (type < 0 || type >= N_SUPPORTED_FLOPPY_TYPES) {
            return -EINVAL;
        }

        /* Update the floppy type and sizes */
        current_floppy[drive] = type;
        update_drive_sizes(drive);
    } else {
        if (check_disk_change(drive)) {
            return -ENODEV;
        }

        /* Update user parameters and manage buffer cache */
        memcpy(&floppy_params[drive], g, sizeof(struct floppy_struct));
        invalidate_buffer_cache(bdev);
    }

    return 0;
}

int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev) {
    if (!g) {
        return -EINVAL;
    }

    if (type != -1) {
        if (!capable(CAP_SYS_ADMIN)) {
            return -EPERM;
        }
        /* Update the floppy type and sizes */
        if (drive >= N_DRIVE || !floppy[drive]) {
            return -EINVAL;
        }
        if (g->track > 255 || g->head > 1 || g->sector > 128 || g->sectors > 63) {
            return -EINVAL;
        }
        floppy[drive]->track = g->track;
        floppy[drive]->head = g->head;
        floppy[drive]->sector = g->sector;
        floppy[drive]->sectors = g->sectors;
        floppy[drive]->hardsect = g->hardsect;
        floppy[drive]->size = g->size;
        floppy[drive]->capacity = g->capacity;
        floppy[drive]->time = g->time;
        floppy[drive]->ps = g->ps;
    } else {
        if (drive >= N_DRIVE || !floppy[drive]) {
            return -EINVAL;
        }
        if (g->track > 255 || g->head > 1 || g->sector > 128 || g->sectors > 63) {
            return -EINVAL;
        }
        if (floppy[drive]->track != g->track || floppy[drive]->head != g->head ||
            floppy[drive]->sector != g->sector || floppy[drive]->sectors != g->sectors) {
            invalidate floppy[drive]->bdev;
        }
        floppy[drive]->track = g->track;
        floppy[drive]->head = g->head;
        floppy[drive]->sector = g->sector;
        floppy[drive]->sectors = g->sectors;
    }

    return 0;
}

int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev) {
    if (!g) {
        return -EINVAL;
    }

    if (type != -1) {
        if (!capable(CAP_SYS_ADMIN)) {
            return -EPERM;
        }

        if (drive >= N_DRIVE || !floppy_drives[drive].exists) {
            return -EINVAL;
        }

        if (type >= N_SUPPORTED_FLOPPY_TYPES) {
            return -EINVAL;
        }

        if (type != FLOPPY_TYPE_CURRENT(drive)) {
            FLOPPY_TYPE(drive) = type;
            update_drive_params(drive);
        }
    } else {
        if (drive >= N_DRIVE || !floppy_drives[drive].exists) {
            return -EINVAL;
        }

        if (check_disk_change(drive)) {
            return -ENODEV;
        }

        memcpy(&floppy_drives[drive].params, g, sizeof(struct floppy_struct));
        invalidate_floppy_buffers(bdev);
    }

    return 0;
}

int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev)
{
    if (!g || drive < 0 || drive >= N_DRIVE)
        return -EINVAL;

    if (type != -1) {
        if (!capable(CAP_SYS_ADMIN))
            return -EPERM;

        if (type >= N_FLOPPY_TYPES)
            return -EINVAL;

        /* Update the floppy type and sizes */
        if (FLOPPY_MAX_DISK_SIZE(type) > FLOPPY_MAX_DISK_SIZE(current_type[drive].fmt))
            return -EINVAL;

        memcpy(&current_type[drive], &floppy_type[type], sizeof(struct floppy_struct));
        update_drive_params(drive);
    } else {
        if (disk_change(drive))
            return -ENODEV;

        /* Handle user parameters and manage buffer cache */
        if (g->size > current_type[drive].size)
            return -EINVAL;

        memcpy(&user_params[drive], g, sizeof(struct floppy_struct));
        invalidate floppy_cache[drive];
    }

    return 0;
}

int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev) {
    if (!g || drive < 0 || drive >= N_DRIVE || (type != -1 && type >= MAX floppy_type)) {
        return -EINVAL;
    }

    if (type != -1) {
        if (!capable(CAP_SYS_ADMIN)) {
            return -EPERM;
        }
        /* Update floppy type and sizes */
        if (type >= N_FLOPPIES || !floppy_type[type].name) {
            return -EINVAL;
        }
        if (drive_info[drive].type != type) {
            drive_info[drive].type = type;
            drive_info[drive].size = floppy_type[type].size;
            update_floppy_capacity(bdev, floppy_type[type].size);
        }
    } else {
        if (check_disk_change(drive)) {
            return -ENODEV;
        }
        if (current->fsuid != bdev->bd_disk->bd_holder->uid) {
            return -EPERM;
        }
        /* Update user parameters */
        drive_info[drive].params = *g;
        invalidate_floppy_buffers(drive);
    }

    return 0;
}
